# Authenticated Tool Calling with the Anthropic SDK
created: 2026-06-01, last updated: 2026-06-10, [Read more](https://www.scalekit.com/blog/tool-calling-anthropic-sdk)

export async function listScopedTools(
userId: string,
connectionNames: string[],
): Promise {
const { tools } = await scalekit.tools.listScopedTools(userId, {
filter: { connectionNames },
pageSize: 100,
});
return tools.map(t => ({
name: t.tool.definition.name as string,
description: t.tool.definition.description as string,
input_schema: t.tool.definition.input_schema as Anthropic.Tool['input_schema'],
}));
}
export async function executeTool(
toolName: string,
toolInput: Record,
userId: string,
): Promise {
// Route to the correct connector by tool name prefix
const connector = toolName.startsWith('slack_')
? config.SLACK_CONNECTION
: toolName.startsWith('sanitymcp_')
? config.SANITY_CONNECTION
: undefined;
const result = await scalekit.actions.executeTool({
toolName,
identifier: userId,
toolInput,
...(connector && { connector }),
});
return JSON.stringify(result.data);
}
