import { ScalekitClient } from '@scalekit-sdk/node';
import 'dotenv/config';

async function main() {
  const envUrl = process.env.SCALEKIT_ENV_URL;
  const clientId = process.env.SCALEKIT_CLIENT_ID;
  const clientSecret = process.env.SCALEKIT_CLIENT_SECRET;

  if (!envUrl || !clientId || !clientSecret) {
    console.error('Missing Scalekit environment variables.');
    process.exit(1);
  }

  const sk = new ScalekitClient(envUrl, clientId, clientSecret);

  console.log('Listing tools for zealt-user01 on connection github-test...');
  try {
    const { tools } = await sk.tools.listScopedTools('zealt-user01', {
      filter: { connectionNames: ['github-test'] },
      pageSize: 100,
    });

    console.log(`Found ${tools.length} tools:`);
    for (const t of tools) {
      console.log(`- ${t.tool.definition.name}: ${t.tool.definition.description}`);
      console.log('  Input Schema:', JSON.stringify(t.tool.definition.inputSchema, null, 2));
    }
  } catch (error) {
    console.error('Error listing tools:', error);
  }
}

main();

