import { ScalekitClient } from '@scalekit-sdk/node';
import 'dotenv/config';

async function main() {
  const envUrl = process.env.SCALEKIT_ENV_URL;
  const clientId = process.env.SCALEKIT_CLIENT_ID;
  const clientSecret = process.env.SCALEKIT_CLIENT_SECRET;

  if (!envUrl || !clientId || !clientSecret) {
    console.error('Missing Scalekit environment variables.');
    process.exit(1);
  }

  const sk = new ScalekitClient(envUrl, clientId, clientSecret);

  console.log('Testing executeTool using scalekit.actions.executeTool...');
  try {
    const result = await sk.actions.executeTool({
      toolName: 'github_user_repos_list',
      identifier: 'zealt-user01',
      toolInput: {
        per_page: 100,
      },
      connector: 'github-test',
    });

    console.log('Success with scalekit.actions.executeTool!');
    console.log('Result keys:', Object.keys(result));
    console.log('Result data:', JSON.stringify(result.data, null, 2));
  } catch (error) {
    console.error('Error with scalekit.actions.executeTool:', error);
  }
}

main();

